documents.advs:
yamaa: '1.0'
type: spec
domain: ADVS
keys: [USUBJID]
input: {VS: {path: never-read.csv, types: {SBPSUP: float, SBPSTD: float}}}
output: {path: advs.csv, columns: [USUBJID, OHYPO]}
columns:
  - {name: USUBJID, type: str, derivation: VS.USUBJID}
  - {name: SBPSUP, type: float, derivation: VS.SBPSUP}
  - {name: SBPSTD, type: float, derivation: VS.SBPSTD}

documents.flag:
yamaa: '1.0'
type: spec
domain: TEST
keys: [ID]
input: {DM: never-read.csv}
output: {path: result.csv, columns: [ID, B, F]}
columns:
  - {name: ID, type: str, derivation: DM.ID}
  - {name: B, type: int, derivation: 2}
  - {name: F, type: str, derivation: {flag: {condition: 'B > 1', false_value: "N"}}}

edits.to:
- {name: SBPSTD, type: float, derivation: VS.SBPSTD}
- name: OHYPO
  type: str
  derivation:
    case:
      - {when: 'SBPSTD - SBPSUP <= -20', then: "'Y'"}
      - {otherwise: "'N'"}

  - {name: SBPSTD, type: float, derivation: VS.SBPSTD}
  - {name: OHYPO, type: str, derivation: "'N'"}
filter: 'VS.SBPSTD - VS.SBPSUP < 0'

  - {name: SBPSTD, type: float, derivation: VS.SBPSTD}
  - {name: OHYPO, type: str, derivation: "'N'"}
verifications:
  - {assert: {when: "OHYPO = 'Y'", require: 'SBPSTD - SBPSUP <= -20'}}
